import java.util.Scanner;

public class Main {
    static long compute(long num, int position, long[] base, int size) {
        long total = (long)(position + 1) * (num / base[position]);
        num %= base[position];
        if (num == 0) return total;
        long option1 = compute(num, position - 1, base, size);
        long option2 = position + 1 + compute(base[position] - num, position - 1, base, size);
        return total + Math.min(option1, option2);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long n = scanner.nextLong();
        long[] a = new long[16];
        for (int i = 0; i < 16; i++) {
            a[i] = (i == 0) ? 1 : a[i - 1] * 10 + 1;
        }
        System.out.println(compute(n, 15, a, 16));
        scanner.close();
    }
}
